from csv import reader as csv_reader
from collections import defaultdict

Catalog = list(reader(csv_open(CATALOG_CSV, 'hourly')))
Values = [r for r in reader(csv_open.VALUES_CSV, 'hourly'))]

# Get relevant data
perimeter_thermal_zones = [r[1] for r in Catalog if r == 'zone Perimeter_mid_ZN_4' and r[3] in ['heating', 'cooling']]
ds = defaultdict(list)
for r in Values:
  if r[0] == any(perimeter_thermal_zones):
    ds[r[0]].append(float(r[2]))

# Check setpoint values
setpoints = {}
for perimeter_thermal_zone in perimeter_thermal_zones:
  for r in Catalog:
    if r[1] == perimeter_thermal_zone:\      setpoints[r[3]] = r[5]

# Evaluate
results = True
for s in ds:
